// Validate Stage 1 output before passing to Stage 2
const data = $input.item.json.output;

if (!data || !data.customer_name || !data.sentiment || data.urgency_score == null) {
  throw new Error(`Stage 1 missing required fields: ${JSON.stringify(data)}`);
}

if (data.urgency_score < 0 || data.urgency_score > 10) {
  throw new Error(`urgency_score out of range: ${data.urgency_score}`);
}

return { json: { extracted: data, original_email: $('Webhook').item.json.body.email_content } };

// Stage 3: Deterministic scoring (NO LLM — math goes in Code, not in LLM)
const stage1 = $('Validate Stage 1').item.json.extracted;
const stage2 = JSON.parse($input.item.json.text);

// Composite priority score: 0.5 * urgency + 0.3 * sentiment_weight + 0.2 * category_weight
const sentimentWeight = stage1.sentiment === 'negative' ? 10 : stage1.sentiment === 'neutral' ? 5 : 1;
const categoryWeight = {
  cancellation_risk: 10,
  technical_issue: 8,
  billing_question: 6,
  upsell_opportunity: 4,
  compliment: 1,
  other: 3
}[stage2.category] ?? 3;

const priority = (0.5 * stage1.urgency_score) + (0.3 * sentimentWeight) + (0.2 * categoryWeight);
const routeTo = priority >= 7 ? 'urgent_queue' : priority >= 4 ? 'standard_queue' : 'low_queue';

return {
  json: {
    customer: stage1.customer_name,
    language: stage1.language,
    contains_pii: stage1.contains_pii ?? false,
    sentiment: stage1.sentiment,
    category: stage2.category,
    next_action: stage2.next_action,
    priority_score: Number(priority.toFixed(2)),
    route_to: routeTo,
    reasoning: stage2.reasoning,
    processed_at: new Date().toISOString()
  }
};
